    public static function findProvinceBySlug(string $slug): ?array
    {
        foreach (self::provinces() as $item) {
            if ($item['slug'] === $slug) {
                return $item;
            }
        }

        return null;
    }

    public static function findCityBySlug(string $slug): ?array
    {
        foreach (self::cities() as $item) {
            if ($item['slug'] === $slug) {
                return $item;
            }
        }

        return null;
    }

    /**
     * @return array<int, array{province_code: string, province: string, province_slug: string, code: string, name: string, type: string, slug: string}>
     */
    public static function citiesByProvinceSlug(string $provinceSlug): array
    {
        return array_values(array_filter(
            self::cities(),
            fn ($city) => $city['province_slug'] === $provinceSlug
        ));
    }
